1|// Live scene id for the continuous reader. The reading column updates the
2|// URL with replaceState (no route remounts), which App Router state may
3|// not observe, so BookView publishes here and Reader subscribes. The URL
4|// stays the deep-link source of truth; this is only the live mirror.
5|import { useSyncExternalStore } from "react";
6|
7|let current: string | null = null;
8|const listeners = new Set<() => void>();
9|
10|export function getCurrentSceneId(): string | null {
11|  return current;
12|}
13|
14|export function setCurrentSceneId(id: string | null): void {
15|  if (id === current) return;
16|  current = id;
17|  for (const notify of [...listeners]) notify();
18|}
19|
20|export function subscribeCurrentSceneId(notify: () => void): () => void {
21|  listeners.add(notify);
22|  return () => {
23|    listeners.delete(notify);
24|  };
25|}
26|
27|export function useCurrentSceneId(): string | null {
28|  return useSyncExternalStore(subscribeCurrentSceneId, getCurrentSceneId, getCurrentSceneId);
29|}
30|
31|// Chapter jumps and pager moves ask the reading column to scroll instead
32|// of pushing a route. BookView owns the only listener.
33|export const GOTO_SCENE_EVENT = "lectoria:goto-scene";
34|
35|export function requestGotoScene(sceneId: string): void {
36|  window.dispatchEvent(new CustomEvent<string>(GOTO_SCENE_EVENT, { detail: sceneId }));
37|}

Read text file `app/leer/book-view.tsx`.
1|// The whole book as one continuous scroll: every chapter with its panels
2|// strip inline, every scene a section. The scene most in view drives the
3|// picture card, the vault, the pager, and the music session. Native
4|// scrolling only: no wheel hijacking, no sub-pages, no page-turn keys.
5|"use client";
6|
7|import { Fragment, useCallback, useEffect, useMemo, useRef, useState } from "react";
8|import type { ReaderModel } from "@/core/reader";
9|import { effectiveImageStylePref, loadImageStylePref, saveImageStylePref } from "../image-style";
10|import type { ImageStylePref } from "../image-style";
11|import { useSkin } from "../use-skin";
12|import { BandPager, Divider } from "../folio/chrome";
13|import { figuresAfter, groupFiguresByEndN } from "../folio/figure-placement";
14|import { ImagePane } from "../folio/image-pane";
15|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
16|import { Lightbox } from "../folio/lightbox";
17|import { usePictures } from "../folio/use-pictures";
18|import type { InlineFigure } from "../folio/use-pictures";
19|import { PictureVault } from "../folio/vault";
20|import {
21|  chapterSetAside,
22|  coverTitleLong,
23|  markChapterEndReached,
24|  markChapterSetAside,
25|  markPanelsShownAnyway,
26|  panelsUnlocked,
27|} from "../folio/panels";
28|import type { ChapterPanel } from "../folio/panels";
29|import { PanelsModal, PanelsOfferCard, PanelsQuietLink, SpoilerGateDialog } from "../folio/panels-modal";
30|import { GOTO_SCENE_EVENT, setCurrentSceneId } from "./current-scene";
31|import { attachFollowPause, pickCurrentScene, scrollToSceneId } from "./scroll-helpers";
32|
33|function pulse(el: HTMLElement | null) {
34|  if (!el) return;
35|  el.classList.remove("pulse");
36|  void el.offsetWidth;
37|  el.classList.add("pulse");
38|  window.setTimeout(() => el.classList.remove("pulse"), 650);
39|}
40|
41|export function BookView({
42|  model,
43|  initialSceneId,
44|  panelsByChapter,
45|}: {
46|  model: ReaderModel;
47|  initialSceneId: string;
48|  panelsByChapter: { ch: number; panels: ChapterPanel[] }[];
49|}) {
50|  const [storedPref, setStoredPref] = useState<ImageStylePref | null>(null);
51|  // Server render uses the default so hydration matches; the live skin
52|  // applies on mount via useSyncExternalStore.
53|  const skin = useSkin();
54|  const pref = effectiveImageStylePref(storedPref, skin);
55|  const [currentId, setCurrentId] = useState(initialSceneId);
56|  const [panelsCh, setPanelsCh] = useState<number | null>(null);
57|  const [gateCh, setGateCh] = useState<number | null>(null);
58|  const [aside, setAside] = useState<Record<number, boolean>>({});
59|  const gateOpener = useRef<HTMLElement | null>(null);
60|  const readColRef = useRef<HTMLDivElement | null>(null);
61|  const figEls = useRef(new Map<string, HTMLElement>());
62|  const maxChRef = useRef(0);
63|  const pic = usePictures({ bookId: model.bookId, textVersion: model.textVersion, sceneId: currentId, pref });
64|
65|  const order = useMemo(() => model.chapters.flatMap((c) => c.scenes.map((s) => s.id)), [model]);
66|  const sceneOf = useMemo(() => {
67|    const map = new Map<string, { ch: number; k: number; n: number; chapterTitle: string }>();
68|    for (const chapter of model.chapters) {
69|      chapter.scenes.forEach((s, i) => {
70|        map.set(s.id, { ch: chapter.ch, k: i + 1, n: chapter.scenes.length, chapterTitle: chapter.title });
71|      });
72|    }
73|    return map;
74|  }, [model]);
75|  const panelsOf = useMemo(() => new Map(panelsByChapter.map((e) => [e.ch, e.panels])), [panelsByChapter]);
76|  const titles = useMemo(() => new Map(model.chapters.map((c) => [c.ch, c.title])), [model]);
77|  const info = sceneOf.get(currentId);
78|  const bookIndex = order.indexOf(currentId);
79|  const lastChapter = model.chapters[model.chapters.length - 1]?.ch ?? 0;
80|
81|  // One commit path for every scene change: state, the live store the
82|  // music container reads, and the deep-link URL. No router pushes, so
83|  // scrolling never remounts.
84|  const commitScene = useCallback((id: string) => {
85|    setCurrentId((prev) => (prev === id ? prev : id));
86|    setCurrentSceneId(id);
87|    window.history.replaceState(null, "", `/leer/${id}`);
88|  }, []);
89|
90|  // Reading past a chapter unlocks its panels, like reaching the old end
91|  // page did. Backward scrolling never relocks.
92|  useEffect(() => {
93|    const at = model.chapters.findIndex((c) => c.ch === info?.ch);
94|    if (at > maxChRef.current) {
95|      for (let i = maxChRef.current; i < at; i++) {
96|        const ch = model.chapters[i]?.ch;
97|        if (ch !== undefined) markChapterEndReached(ch);
98|      }
99|      maxChRef.current = at;
100|    }
101|  }, [info, model.chapters]);
102|
103|  // Land on the deep-linked scene with no animation, focus the column so
104|  // native keys scroll it, and pause narration follow on user input.
105|  useEffect(() => {
106|    const col = readColRef.current;
107|    if (!col) return;
108|    col.focus({ preventScroll: true });
109|    setCurrentSceneId(initialSceneId);
110|    scrollToSceneId(col, initialSceneId, false);
111|    return attachFollowPause(col);
112|  }, [initialSceneId]);
113|
114|  // The scene under the reading line (40% down the column) is current.
115|  // A thin rootMargin band, not ratios: a long scene filling the screen
116|  // must beat a short one fully in view, and the band fires exactly when
117|  // a section crosses the line. Ties keep document order. One observer,
118|  // no scroll listeners, no layout reads on scroll.
119|  useEffect(() => {
120|    const col = readColRef.current;
121|    if (!col) return;
122|    const seen = new Map<string, { id: string; ratio: number }>();
123|    const io = new IntersectionObserver(
124|      (entries) => {
125|        for (const entry of entries) {
126|          const id = (entry.target as HTMLElement).dataset.sceneId;
127|          if (!id) continue;
128|          if (entry.isIntersecting) seen.set(id, { id, ratio: entry.intersectionRatio });
129|          else seen.delete(id);
130|        }
131|        const next = pickCurrentScene(order, seen);
132|        if (next) commitScene(next);
133|      },
134|      { root: col, rootMargin: "-40% 0px -59% 0px", threshold: 0 },
135|    );
136|    for (const section of col.querySelectorAll("[data-scene-id]")) io.observe(section);
137|    return () => io.disconnect();
138|  }, [order, commitScene]);
139|
140|  // Chapter jumps from outside the column arrive here.
141|  useEffect(() => {
142|    const onGoto = (event: Event) => gotoScene((event as CustomEvent<string>).detail);
143|    window.addEventListener(GOTO_SCENE_EVENT, onGoto);
144|    return () => window.removeEventListener(GOTO_SCENE_EVENT, onGoto);
145|  }, [gotoScene]);
146|
147|  useEffect(() => {
148|    setStoredPref(loadImageStylePref());
149|  }, []);
150|
151|  function changePref(next: ImageStylePref) {
152|    setStoredPref(next);
153|    saveImageStylePref(next);
154|  }
155|
156|  function requestPanels(ch: number, opener: HTMLElement | null) {
157|    if (panelsUnlocked(ch)) {
158|      setPanelsCh(ch);
159|      return;
160|    }
161|    gateOpener.current = opener;
162|    setGateCh(ch);
163|  }
164|
165|  function showAnyway() {
166|    if (gateCh === null) return;
167|    markPanelsShownAnyway(gateCh);
168|    setGateCh(null);
169|    setPanelsCh(gateCh);
170|  }
171|
172|  function notYet() {
173|    setGateCh(null);
174|    gateOpener.current?.focus?.();
175|    gateOpener.current = null;
176|  }
177|
178|  function readFirst(ch: number) {
179|    markChapterSetAside(ch);
180|    setAside((prev) => ({ ...prev, [ch]: true }));
181|  }
182|
183|  function showChapterAnyway(ch: number) {
184|    markPanelsShownAnyway(ch);
185|    setPanelsCh(ch);
186|  }
187|
188|  const figsByN = useMemo(() => groupFiguresByEndN(pic.figures), [pic.figures]);
189|
190|  function gotoFigure(fig: InlineFigure) {
191|    const el = figEls.current.get(fig.id) ?? null;
192|    el?.scrollIntoView({ block: "nearest" });
193|    pulse(el);
194|  }
195|
196|  function gotoScenePicture() {
197|    const img = document.querySelector(".img-pane .pane-img");
198|    pulse(img instanceof HTMLElement ? img : null);
199|  }
200|
201|  function gotoScene(id: unknown) {
202|    if (typeof id !== "string") return;
203|    pic.hidePopover();
204|    const col = readColRef.current;
205|    if (col) scrollToSceneId(col, id, true);
206|  }
207|
208|  // A selection that starts in another scene moves the current scene
209|  // there; the popover follows without a second tap. Chapter headings and
210|  // the panels strip sit outside scene sections, so they never offer it.
211|  function onReadMouseUp() {
212|    const sel = window.getSelection();
213|    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
214|    const node = sel.anchorNode;
215|    const el = node instanceof Element ? node : node?.parentElement ?? null;
216|    const section = el?.closest?.("[data-scene-id]") ?? null;
217|    const id = section instanceof HTMLElement ? section.dataset.sceneId : null;
218|    if (!id || id === currentId) return;
219|    commitScene(id);
220|    requestAnimationFrame(() => pic.rescan());
221|  }
222|
223|  return (
224|    <>
225|      <ImagePane
226|        card={pic.card}
227|        onPicture={() => pic.illustrateScene()}
228|        onRetry={() => pic.illustrateScene()}
229|        onClear={pic.clearScene}
230|        onOpen={pic.lightbox.open}
231|        onPictureChapter={info ? (opener) => requestPanels(info.ch, opener) : null}
232|      />
233|      <Divider />
234|      <div className="read-col" ref={readColRef} tabIndex={-1} aria-label="Reading column" onMouseUp={onReadMouseUp}>
235|        {model.chapters.map((chapter) => {
236|          const panels = panelsOf.get(chapter.ch) ?? [];
237|          const coverLong = coverTitleLong(chapter.title);
238|          const setAside = aside[chapter.ch] ?? chapterSetAside(chapter.ch);
239|          return (
240|            <div className="chapter-block" key={chapter.ch}>
241|              <div className="kicker">Chapter</div>
242|              <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${chapter.ch}`}>
243|                {chapter.ch}
244|              </p>
245|              <h1 className="chapter-title cover-title" data-long={coverLong}>
246|                {chapter.title}
247|              </h1>
248|              <hr className="cover-rule" />
249|              {setAside ? (
250|                <PanelsQuietLink onOpen={(el) => requestPanels(chapter.ch, el)} />
251|              ) : (
252|                <PanelsOfferCard
253|                  panels={panels}
254|                  onShowAnyway={() => showChapterAnyway(chapter.ch)}
255|                  onReadFirst={() => readFirst(chapter.ch)}
256|                />
257|              )}
258|              {chapter.scenes.map((s, si) => (
259|                <section key={s.id} className="book-section" data-scene-id={s.id} aria-label={s.title}>
260|                  <div
261|                    className={si === 0 ? "body-text dropcap" : "body-text"}
262|                    ref={s.id === currentId ? pic.viewRef : undefined}
263|                  >
264|                    {s.paragraphs.map((p, i, arr) => (
265|                      <Fragment key={p.id}>
266|                        <p id={p.id} data-n={p.n}>
267|                          {p.text}
268|                        </p>
269|                        {figuresAfter(arr, i, figsByN).map((fig) => (
270|                          <InlineFigureView
271|                            key={fig.id}
272|                            figure={fig}
273|                            onRemove={() => pic.removeFigure(fig.id)}
274|                            onRetry={() => pic.retryFigure(fig.id)}
275|                            onOpen={pic.lightbox.open}
276|                            refCb={(el) => {
277|                              if (el) figEls.current.set(fig.id, el);
278|                              else figEls.current.delete(fig.id);
279|                            }}
280|                          />
281|                        ))}
282|                      </Fragment>
283|                    ))}
284|                    {s.id === currentId && pic.popover !== null ? (
285|                      <SelectionPopover pos={pic.popover} popRef={pic.popRef} onPick={() => pic.illustratePassage()} />
286|                    ) : null}
287|                  </div>
288|                </section>
289|              ))}
290|              {chapter.ch === lastChapter ? (
291|                <p className="the-end">The end.</p>
292|              ) : (
293|                <div className="chapter-relive">
294|                  <button
295|                    type="button"
296|                    className="panels-link"
297|                    onClick={(e) => requestPanels(chapter.ch, e.currentTarget)}
298|                  >
299|                    Relive this chapter in panels
300|                  </button>
301|                </div>
302|              )}
303|            </div>
304|          );
305|        })}
306|      </div>
307|      <PictureVault
308|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
309|        figures={pic.figures}
310|        onGotoScene={gotoScenePicture}
311|        onGotoFigure={gotoFigure}
312|        onOpen={pic.lightbox.open}
313|        pref={pref}
314|        onPrefChange={changePref}
315|      />
316|      <BandPager
317|        k={info?.k ?? 1}
318|        n={info?.n ?? 1}
319|        bookIndex={Math.max(0, bookIndex)}
320|        bookTotal={order.length}
321|        onPrev={() => gotoScene(bookIndex > 0 ? order[bookIndex - 1] : undefined)}
322|        onNext={() => gotoScene(bookIndex < order.length - 1 ? order[bookIndex + 1] : undefined)}
323|        atStart={bookIndex <= 0}
324|        atBookEnd={bookIndex >= order.length - 1}
325|      />
326|      <Lightbox item={pic.lightbox.item} onClose={pic.lightbox.close} />
327|      {gateCh !== null ? <SpoilerGateDialog onShow={showAnyway} onNotYet={notYet} /> : null}
328|      {panelsCh !== null ? (
329|        <PanelsModal
330|          ch={panelsCh}
331|          chapterTitle={titles.get(panelsCh) ?? ""}
332|          panels={panelsOf.get(panelsCh) ?? []}
333|          onClose={() => setPanelsCh(null)}
334|          onOpenArt={pic.lightbox.open}
335|        />
336|      ) : null}
337|    </>
338|  );
339|}

