1|// Continuous-scroll helpers: pure scene picking, section jumps, and the
2|// narration auto-follow pause. No React, no listeners on scroll (the
3|// observer in book-view.tsx owns scroll position without layout reads).
4|export interface SceneVisibility {
5|  id: string;
6|  ratio: number;
7|}
8|
9|// Current scene = the visible section with the largest intersection ratio.
10|// Ties keep document order, so the upper section wins at exact 50/50 and
11|// the id only changes once the lower one dominates. Null when nothing is
12|// visible; the caller keeps the previous id.
13|export function pickCurrentScene(order: string[], visible: Map<string, SceneVisibility>): string | null {
14|  let best: string | null = null;
15|  let bestRatio = 0;
16|  for (const id of order) {
17|    const entry = visible.get(id);
18|    const ratio = entry && entry.id === id ? entry.ratio : 0;
19|    if (ratio > bestRatio) {
20|      bestRatio = ratio;
21|      best = id;
22|    }
23|  }
24|  return best;
25|}
26|
27|export function prefersReducedMotion(): boolean {
28|  return (
29|    typeof window !== "undefined" &&
30|    typeof window.matchMedia === "function" &&
31|    window.matchMedia("(prefers-reduced-motion: reduce)").matches
32|  );
33|}
34|
35|// Scroll the scroller so the scene section sits at its top; a chapter's
36|// first scene lands on the chapter heading instead. Instant when
37|// smooth is false or the user prefers reduced motion. False when the
38|// section is missing. scrollIntoView also renders content-visibility
39|// sections on the way there.
40|export function scrollToSceneId(scroller: HTMLElement, sceneId: string, smooth = true): boolean {
41|  const el = scroller.querySelector(`[data-scene-id="${sceneId}"]`);
42|  if (!el || typeof el.scrollIntoView !== "function") return false;
43|  const block = el.closest?.(".chapter-block");
44|  const target = block && block.querySelector("[data-scene-id]") === el ? block : el;
45|  target.scrollIntoView({
46|    block: "start",
47|    behavior: smooth && !prefersReducedMotion() ? "smooth" : "auto",
48|  });
49|  return true;
50|}
51|
52|// Narration auto-follow pause: the last user-driven scroll moment per
53|// scroller. Listeners attach once per scroller and stay passive.
54|const lastUserScroll = new WeakMap<object, number>();
55|
56|export function noteUserScroll(scroller: object, now: number = Date.now()): void {
57|  lastUserScroll.set(scroller, now);
58|}
59|
60|export function attachFollowPause(scroller: HTMLElement): () => void {
61|  const mark = () => noteUserScroll(scroller);
62|  scroller.addEventListener("wheel", mark, { passive: true });
63|  scroller.addEventListener("touchstart", mark, { passive: true });
64|  window.addEventListener("keydown", mark);
65|  return () => {
66|    scroller.removeEventListener("wheel", mark);
67|    scroller.removeEventListener("touchstart", mark);
68|    window.removeEventListener("keydown", mark);
69|  };
70|}
71|
72|// Keep the spoken word in a comfortable band (middle 60% of the scroller
73|// viewport). Scrolls only when the element leaves the band, and never
74|// within pauseMs of a user scroll. Returns true when it scrolled.
75|export function followIntoView(
76|  el: HTMLElement,
77|  scroller: HTMLElement,
78|  now: number = Date.now(),
79|  pauseMs = 4000,
80|): boolean {
81|  const last = lastUserScroll.get(scroller) ?? Number.NEGATIVE_INFINITY;
82|  if (now - last < pauseMs) return false;
83|  const frame = scroller.getBoundingClientRect();
84|  const box = el.getBoundingClientRect();
85|  const top = frame.top + frame.height * 0.2;
86|  const bottom = frame.top + frame.height * 0.8;
87|  let delta = 0;
88|  if (box.top < top) delta = box.top - top;
89|  else if (box.bottom > bottom) delta = box.bottom - bottom;
90|  if (delta === 0) return false;
91|  scroller.scrollTop += delta;
92|  return true;
