11|// Horizontal fit for the engraving overlay: the small-caps face runs
12|// wider than the in-flow word, so shrink it to the measured word rect.
13|// Never stretches, never divides by zero.
14|export function engravingScale(markWidth: number, naturalWidth: number): number {
15|  if (!Number.isFinite(markWidth) || !Number.isFinite(naturalWidth) || markWidth <= 0 || naturalWidth <= 0) {
