55|  audioRef: RefObject<HTMLAudioElement | null>;
56|  manifest: ChapterNarration | null;
57|  span: { startSec: number; endSec: number } | null;
58|  containerRef: RefObject<HTMLElement | null>;
59|  scrollerRef: RefObject<HTMLElement | null>;
60|  pages: { paragraphs: SyncFragment[] }[];
61|  textPage: number;
62|  onTurnPage: (textIndex: number) => void;
63|  lastManualRef: RefObject<number | null>;
