65|  const [treatment, setTreatment] = useState<HighlightTreatment>(skinTreatment);
66|  const [mark, setMark] = useState<MarkRect | null>(null);
67|  const [active, setActive] = useState<ActiveSpot | null>(null);
68|
69|  const live = useRef(opts);
70|  live.current = opts;
71|
72|  // A skin switch restyles the mark live: data-skin is picked whenever
73|  // it is available, with engraving as the default.
74|  useEffect(() => {
75|    const root = document.documentElement;
76|    const sync = () => setTreatment(skinTreatment());
77|    sync();
78|    const obs = new MutationObserver(sync);
79|    obs.observe(root, { attributes: true, attributeFilter: ["data-skin"] });
