81|  }, []);
82|
83|  // The follow loop: audio time in, chunk/word out, one auto-turn gate.
84|  useEffect(() => {
85|    const { enabled, manifest } = live.current;
86|    if (!enabled || !manifest) {
87|      setActive(null);
88|      return;
89|    }
90|    let raf = 0;
91|    const tick = () => {
92|      raf = requestAnimationFrame(tick);
93|      // Every input is read live each tick: the scene (and its span)
94|      // can change under a kept chapter manifest, so a closed-over
95|      // span would gate the voice against the previous scene.
96|      const seen = live.current;
97|      if (!seen.enabled || !seen.manifest) return;
98|      const audio = seen.audioRef.current;
99|      if (!audio || audio.paused) return;
100|      const t = audio.currentTime;
101|      const span = seen.span;
102|      if (span !== null && (t < span.startSec - 0.3 || t > span.endSec + 2)) return;
103|      const heard = seen.manifest;
104|      const ci = activeChunkAt(heard.chunks, t);
105|      if (ci < 0) {
106|        setActive((prev) => (prev === null ? prev : null));
107|        return;
108|      }
109|      const chunk = heard.chunks[ci] as ChapterNarration["chunks"][number];
