119|      if (target !== null) seen.onTurnPage(target);
120|    };
121|    raf = requestAnimationFrame(tick);
122|    return () => cancelAnimationFrame(raf);
123|  }, [opts.enabled, opts.manifest]);
124|
125|  // Measure the active word against the fragment DOM and paint the
126|  // sentence tint through the Highlight API (no-op where unsupported).
127|  useLayoutEffect(() => {
128|    const { containerRef, scrollerRef, manifest } = live.current;
129|    const container = containerRef.current;
130|    clearSentence();
131|    if (!container || !manifest || active === null) {
132|      setMark(null);
133|      return;
134|    }
135|    const chunk = manifest.chunks[active.chunk];
136|    if (!chunk) {
137|      setMark(null);
138|      return;
139|    }
140|    const { word: wordRange, wordText, sentence } = rangesForChunk(container, chunk, active.word);
