142|    if (!wordRange) {
143|      setMark(null);
144|      return;
145|    }
146|    const rects = (wordRange as Range).getClientRects();
147|    if (rects.length === 0) {
148|      setMark(null);
149|      return;
150|    }
151|    let left = Infinity;
152|    let top = Infinity;
153|    let right = -Infinity;
154|    let bottom = -Infinity;
155|    for (const r of rects) {
156|      left = Math.min(left, r.left);
157|      top = Math.min(top, r.top);
158|      right = Math.max(right, r.right);
159|      bottom = Math.max(bottom, r.bottom);
160|    }
