1|// Auto page-turn gate: the voice follows the text across sub-pages and
2|// scenes on its own, unless the reader just moved by hand. A recent
3|// manual move means the voice keeps reading without yanking the page.
4|export const NARRATION_MANUAL_WINDOW_MS = 8000;
5|
6|export function shouldAutoTurn(
7|  lastManualAtMs: number | null,
8|  nowMs: number,
9|  windowMs: number = NARRATION_MANUAL_WINDOW_MS,
10|): boolean {
11|  if (lastManualAtMs === null) return true;
12|  return nowMs - lastManualAtMs >= windowMs;
13|}
14|
15|// Target text-page index for the follow loop, or null to stay. The
16|// lookup runs in text-page space (the cover shifts sub-pages by one,
17|// which scene-page adds back in onTurnPage), and a recent manual move
18|// holds the turn without stopping the voice.
19|export function autoTurnTarget(
20|  pages: { paragraphs: { n: number }[] }[],
21|  chunkN: number,
22|  textPage: number,
23|  lastManualAtMs: number | null,
24|  nowMs: number,
25|): number | null {
26|  const at = pages.findIndex((pg) => pg.paragraphs.some((p) => p.n === chunkN));
27|  if (at < 0 || at === textPage) return null;
28|  return shouldAutoTurn(lastManualAtMs, nowMs) ? at : null;
29|}

