1|// Music duck while the voice plays: about -18 dB, ramped down over
2|// ~400 ms and back up over ~800 ms so the dip never clicks.
3|export const NARRATION_DUCK_DB = -18;
4|export const NARRATION_DUCK_DOWN_MS = 400;
5|export const NARRATION_DUCK_UP_MS = 800;
6|
7|// 10^(-18/20): the music multiplier at full duck.
8|export const NARRATION_DUCK_LEVEL = 10 ** (NARRATION_DUCK_DB / 20);
9|
10|// One ramp step toward target: an exponential approach that lands
11|// exactly when the elapsed slice covers the duration. Pure, so the
12|// controller and the tests share the curve.
13|export function rampDuck(current: number, target: number, dtMs: number, durationMs: number): number {
14|  if (!(dtMs > 0)) return current;
15|  if (!(durationMs > 0)) return target;
16|  const next = current + (target - current) * Math.min(1, dtMs / durationMs);
17|  // Snap when close so the ramp settles instead of easing forever.
18|  return Math.abs(next - target) < 1e-4 ? target : next;
19|}

