34|    const start = Math.max(chunk.start, frag.from);
35|    const end = Math.min(chunk.end, frag.from + frag.len);
36|    if (end > start) sentence.push({ frag: index, start: start - frag.from, end: end - frag.from });
37|  });
38|  let word: PlannedWord | null = null;
39|  // The active word is a chunk-global index; the holding fragment is the
40|  // one whose span contains its paragraph-relative start.
41|  const abs = wordIdx >= 0 ? (chunk.w[wordIdx * 4] as number | undefined) : undefined;
42|  if (abs !== undefined) {
43|    const end = chunk.w[wordIdx * 4 + 1] as number;
44|    const at = frags.findIndex((frag) => abs >= frag.from && abs < frag.from + frag.len);
