78|// Throws on unordered scenes and on paragraphs covered zero or two times.
79|export function buildReaderModel(
80|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
81|  analysis: { scenes: AnalyzedScene[] },
82|): ReaderModel {
83|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
84|  const scenes = [...analysis.scenes];
85|  for (let i = 1; i < scenes.length; i++) {
86|    const prev = scenes[i - 1];
87|    const cur = scenes[i];
88|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
89|      throw new Error(`scenes out of order at ${cur.id}`);
90|    }
91|  }
92|  const seen = new Set<number>();
93|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
94|  for (const scene of scenes) {
95|    const paras: ReaderParagraph[] = [];
96|    for (let n = scene.start_n; n <= scene.end_n; n++) {
97|      const p = byN.get(n);
98|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
99|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
100|      seen.add(n);
101|      paras.push({ id: p.id, n: p.n, text: p.text });
102|    }
103|    sceneParagraphs.set(scene.id, paras);
104|  }
105|  if (seen.size !== book.paragraphs.length) {
106|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
107|  }
108|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
109|    const mine = scenes.filter((s) => s.ch === chapter.ch);
110|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
111|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
112|    }
113|    return {
114|      ch: chapter.ch,
115|      title: chapter.title,
116|      scenes: mine.map((s) => ({
117|        id: s.id,
118|        title: s.title,
119|        emotion: s.final === null ? null : { ...s.final },
120|        paragraphs: sceneParagraphs.get(s.id) ?? [],
121|      })),
122|    };
123|  });
