22|
23|const CLOSERS = new Set(["”", "’", '"', "'", ")", "]"]);
24|
25|// Lowercase words that end with a period without ending a sentence.
26|const ABBREVIATIONS = new Set([
27|  "mr", "mrs", "ms", "dr", "st", "mt", "prof", "sr", "jr",
28|  "rev", "lt", "col", "gen", "capt", "sgt", "ave", "blvd", "rd", "no",
29|]);
