31|function isTerminator(char: string): boolean {
32|  return char === "." || char === "!" || char === "?" || char === "…";
33|}
34|
35|function isSpace(char: string | undefined): boolean {
36|  return char === undefined || /\s/.test(char);
37|}
38|
39|// Word of letters directly before index (exclusive), lowercased.
40|function wordBefore(text: string, index: number): string {
41|  let i = index - 1;
42|  while (i >= 0 && /[A-Za-z]/.test(text[i] as string)) i -= 1;
43|  return text.slice(i + 1, index).toLowerCase();
44|}
