51|// Char offsets into the paragraph text, trimmed of surrounding
52|// whitespace, covering every non-space char. A sentence ends at a
53|// terminator plus closing quotes/brackets followed by whitespace.
54|export function splitSentences(text: string): SentenceSpan[] {
55|  const raw: SentenceSpan[] = [];
56|  let pieceStart = -1;
57|  let i = 0;
58|  while (i < text.length) {
59|    const char = text[i] as string;
60|    if (/\s/.test(char)) {
61|      i += 1;
62|      continue;
63|    }
64|    if (pieceStart === -1) pieceStart = i;
65|    if (isTerminator(char)) {
66|      let end = i + 1;
67|      while (end < text.length && CLOSERS.has(text[end] as string)) end += 1;
68|      if (isSpace(text[end])) {
69|        if (char === ".") {
70|          const word = wordBefore(text, i);
71|          const singleInitial = /^[A-Z]$/.test(text.slice(i - 1, i));
72|          if (singleInitial || ABBREVIATIONS.has(word)) {
73|            i += 1;
74|            continue;
75|          }
76|        }
77|        // Trim trailing whitespace inside the piece (there is none:
78|        // the piece ends at a terminator or closer).
79|        raw.push({ start: pieceStart, end });
80|        pieceStart = -1;
81|        i = end;
82|        continue;
83|      }
84|    }
85|    i += 1;
86|  }
87|  if (pieceStart !== -1) {
88|    let end = text.length;
89|    while (end > pieceStart && /\s/.test(text[end - 1] as string)) end -= 1;
90|    raw.push({ start: pieceStart, end });
91|  }
92|  if (raw.length === 0) return [];
93|  // Merge a piece shorter than 3 words into the previous sentence
94|  // (or the next one if first), keeping offsets exact.
95|  const merged: SentenceSpan[] = [];
96|  for (const span of raw) {
97|    const piece = text.slice(span.start, span.end);
98|    if (wordCount(piece) >= 3 || merged.length === 0) {
99|      merged.push({ ...span });
100|      continue;
101|    }
102|    const prev = merged[merged.length - 1] as SentenceSpan;
103|    prev.end = span.end;
104|  }
105|  if (merged.length > 1) {
106|    const first = merged[0] as SentenceSpan;
107|    if (wordCount(text.slice(first.start, first.end)) < 3) {
108|      const next = merged[1] as SentenceSpan;
109|      next.start = first.start;
110|      merged.shift();
111|    }
112|  }
113|  return merged;
