347|      const next = display[k + 1] as { start: number; end: number; norm: string };
348|      if (/\s/.test(text.slice(prev.end, next.start))) break;
349|      joined += next.norm;
350|      k += 1;
351|      if (joined === norms[j]) break;
352|    }
353|    if (k > i && joined === norms[j]) {
354|      const total =
355|        display.slice(i, k + 1).reduce((sum, d) => sum + (d.end - d.start), 0) || 1;
356|      let edge = tok.t0;
357|      for (let m = i; m <= k; m++) {
358|        const part = display[m] as { start: number; end: number; norm: string };
359|        const share = ((part.end - part.start) / total) * (tok.t1 - tok.t0);
360|        timed[m] = { t0: edge, t1: edge + share };
361|        edge += share;
362|      }
363|      i = k + 1;
364|      j += 1;
365|      continue;
366|    }
367|    let advanced = false;
368|    for (let a = 1; a <= 3 && j + a < tokens.length; a++) {
369|      if (norms[j + a] === word.norm) {
370|        j += a;
371|        advanced = true;
372|        break;
373|      }
374|    }
375|    if (!advanced) {
376|      for (let b = 1; b <= 3 && i + b < display.length; b++) {
377|        if ((display[i + b] as { norm: string }).norm === norms[j]) {
378|          i += b;
379|          advanced = true;
380|          break;
381|        }
382|      }
383|    }
384|    if (advanced) continue;
385|    // Neither side matches (a number Kokoro spells out): both move on
386|    // and the display word interpolates below.
387|    i += 1;
388|    j += 1;
389|  }
390|  for (let a = 0; a < display.length; a++) {
391|    if (timed[a] !== null) continue;
392|    let b = a;
393|    while (b + 1 < display.length && timed[b + 1] === null) b += 1;
394|    const lo = a > 0 ? (timed[a - 1] as { t0: number; t1: number }).t1 : span.t0;
395|    const hi = b + 1 < display.length ? (timed[b + 1] as { t0: number; t1: number }).t0 : span.t1;
