397|    const to = Math.max(lo, hi);
398|    const count = b - a + 1;
399|    for (let m = a; m <= b; m++) {
400|      timed[m] = { t0: from + ((to - from) * (m - a)) / count, t1: from + ((to - from) * (m - a + 1)) / count };
