32|  it("covers the sentence across split fragments with no gaps", () => {
33|    const { sentence } = planRanges(FRAGS.map(({ from, text }) => ({ from, len: text.length })), CHUNK, 1);
34|    expect(sentence.map((part) => slice(part.frag, part.start, part.end)).join("")).toBe(TEXT);
