1|"use client";
2|
3|import { useEffect, useRef, useState } from "react";
4|import {
5|  AMBIENCES,
6|  DEFAULT_AMBIENCE_VOLUME,
7|  ambienceLabel,
8|  levelById,
9|  nextLevel,
10|} from "@/core/ambience";
11|import { loadAmbiencePrefs, saveAmbiencePrefs } from "./ambience-prefs";
12|import { AmbienceController } from "./ambience-controller";
13|import { WebAmbienceEngine } from "./ambience-engine";
14|import { Icon, iconSkin } from "./icons";
15|import type { RainIconName } from "./icons-rain";
16|import { useSkin } from "./use-skin";
17|
18|const RAIN = AMBIENCES[0]!;
19|
20|// One drop cycle: how long the button replays its animation after a click.
21|const ANIM_MS = 1400;
22|
23|// The button owns its controller: it loads prefs once, saves on change,
24|// and starts the stored level on the first gesture anywhere in the page.
25|export function RainAmbience({ muted }: { muted: boolean }) {
26|  const controllerRef = useRef<AmbienceController | null>(null);
27|  const [level, setLevel] = useState("off");
28|  const [volume, setVolume] = useState(DEFAULT_AMBIENCE_VOLUME);
29|  const [burst, setBurst] = useState(0);
30|  // Server render uses the default so hydration matches; the live skin
31|  // applies on mount via useSyncExternalStore.
32|  const skin = useSkin();
33|  // Same fallback rule as <Icon>; also drives the per-skin CSS via data-art.
34|  const artSkin = iconSkin(`rain-${level}` as RainIconName, skin);
35|  const burstTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
36|
37|  useEffect(() => {
38|    const controller = new AmbienceController(new WebAmbienceEngine());
39|    controllerRef.current = controller;
40|    const prefs = loadAmbiencePrefs();
41|    if (prefs) {
42|      controller.setVolume(prefs.volume);
43|      setVolume(prefs.volume);
44|      if (prefs.level !== "off" && levelById(RAIN, prefs.level)) {
45|        controller.setLevel(prefs.level);
46|        setLevel(prefs.level);
47|      }
48|    }
49|    const unlock = () => void controller.unlock();
50|    document.addEventListener("pointerdown", unlock, { once: true });
51|    document.addEventListener("keydown", unlock, { once: true });
52|    return () => {
53|      document.removeEventListener("pointerdown", unlock);
54|      document.removeEventListener("keydown", unlock);
55|      controller.dispose();
56|      controllerRef.current = null;
57|    };
58|  }, []);
59|
60|  useEffect(() => {
61|    controllerRef.current?.setMuted(muted);
62|  }, [muted]);
63|
64|  useEffect(
65|    () => () => {
66|      if (burstTimer.current) clearTimeout(burstTimer.current);
67|    },
68|    [],
69|  );
70|
71|  function cycle() {
72|    const controller = controllerRef.current;
73|    if (!controller) return;
74|    void controller.unlock();
75|    const id = nextLevel(RAIN, level);
76|    controller.setLevel(id);
77|    setLevel(id);
78|    saveAmbiencePrefs({ level: id, volume });
79|    setBurst((b) => b + 1);
80|    if (burstTimer.current) clearTimeout(burstTimer.current);
81|    burstTimer.current = setTimeout(() => setBurst(0), ANIM_MS);
82|  }
83|
84|  function changeVolume(value: number) {
85|    controllerRef.current?.setVolume(value);
86|    setVolume(value);
87|    saveAmbiencePrefs({ level, volume: value });
88|  }
89|
90|  const label = ambienceLabel(RAIN, level);
91|  return (
92|    <>
93|      <button
94|        type="button"
95|        className="skip rain"
96|        data-level={level}
97|        data-art={artSkin}
98|        data-anim={burst ? "1" : undefined}
99|        onClick={cycle}
100|        aria-label={label}
101|        title={label}
102|      >
103|        {/* key replays the one-shot animation on rapid clicks */}
104|        <span className="face" key={burst}>
105|          <Icon name={`rain-${level}` as RainIconName} skin={artSkin} />
106|        </span>
107|      </button>
108|      {level !== "off" ? (
109|        <input
110|          type="range"
111|          className="rain-volume"
112|          min={0}
113|          max={1}
114|          step={0.05}
115|          value={volume}
116|          onChange={(e) => changeVolume(Number(e.target.value))}
117|          aria-label="Rain volume"
118|        />
119|      ) : null}
120|    </>
121|  );
122|}

