1|import { describe, expect, it } from "vitest";
2|import { planRanges } from "./ranges";
3|
4|// “Oz’s,” didn’t run split across two fragments: the cut lands on the
5|// space, so each word sits whole in one fragment. Punctuation and curly
6|// quotes never highlight: slicing the fixture texts at the planned
7|// offsets yields letters only.
8|const TEXT = "“Oz’s,” didn’t run";
9|const FRAGS = [
10|  { text: "“Oz’s,”", from: 0 },
11|  { text: " didn’t run", from: 7 },
12|];
13|const CHUNK = { start: 0, end: 18, w: [1, 5, 0.0, 0.4, 8, 14, 0.5, 0.9, 15, 18, 1.0, 1.2] };
14|
15|function slice(frag: number, start: number, end: number): string {
16|  return (FRAGS[frag] as { text: string }).text.slice(start, end);
17|}
18|
19|describe("planRanges", () => {
20|  it("maps each word to its fragment, letters only", () => {
21|    const zero = planRanges(FRAGS.map(({ from, text }) => ({ from, len: text.length })), CHUNK, 0);
22|    expect(zero.word).toMatchObject({ frag: 0, start: 1, end: 5 });
23|    expect(slice(zero.word!.frag, zero.word!.start, zero.word!.end)).toBe("Oz’s");
24|    const one = planRanges(FRAGS.map(({ from, text }) => ({ from, len: text.length })), CHUNK, 1);
25|    expect(one.word).toMatchObject({ frag: 1, start: 1, end: 7 });
26|    expect(slice(one.word!.frag, one.word!.start, one.word!.end)).toBe("didn’t");
27|    const two = planRanges(FRAGS.map(({ from, text }) => ({ from, len: text.length })), CHUNK, 2);
28|    expect(two.word).toMatchObject({ frag: 1, start: 8, end: 11 });
29|    expect(slice(two.word!.frag, two.word!.start, two.word!.end)).toBe("run");
30|  });
31|
32|  it("covers the sentence across split fragments with no gaps", () => {
33|    const { sentence } = planRanges(FRAGS.map(({ from, text }) => ({ from, len: text.length })), CHUNK, 1);
34|    expect(sentence.map((part) => slice(part.frag, part.start, part.end)).join("")).toBe(TEXT);
35|  });
36|
37|  it("returns no word off the words", () => {
38|    const frags = FRAGS.map(({ from, text }) => ({ from, len: text.length }));
39|    expect(planRanges(frags, CHUNK, -1).word).toBeNull();
40|    expect(planRanges(frags, CHUNK, 9).word).toBeNull();
41|  });
42|});

