1|// Rain level, volume, and mute logic against an injected engine, so
2|// tests use a fake. The controller owns fades: fade in from off,
3|// crossfade between playing levels, fade out to off. Nothing starts
4|// before unlock (the user gesture); pending loads never race, so only
5|// the latest level starts and at most two voices are alive at once.
6|import {
7|  AMBIENCES,
8|  CROSSFADE_SEC,
9|  DEFAULT_AMBIENCE_VOLUME,
10|  FADE_IN_SEC,
11|  FADE_OUT_SEC,
12|  MUTE_FADE_SEC,
13|  VOLUME_RAMP_SEC,
14|  ambienceGain,
15|  levelById,
16|} from "@/core/ambience";
17|import type { Ambience, AmbienceSource } from "@/core/ambience";
18|
19|export interface AmbienceVoice {
20|  ramp(gain: number, sec: number): void;
21|  stop(fadeSec: number): void;
22|}
23|
24|export interface AmbienceEngine {
25|  load(sources: AmbienceSource[]): Promise<unknown>;
26|  start(handle: unknown, gain: number, fadeSec: number): AmbienceVoice;
27|  unlock(): Promise<void>;
28|}
29|
30|export class AmbienceController {
31|  private levelId = "off";
32|  private volume = DEFAULT_AMBIENCE_VOLUME;
33|  private muted = false;
34|  private unlocked = false;
35|  private voice: AmbienceVoice | null = null;
36|  private pendingId: string | null = null;
37|  private seq = 0;
38|
39|  constructor(
40|    private engine: AmbienceEngine,
41|    private ambience: Ambience = AMBIENCES[0]!,
42|  ) {}
43|
44|  private targetGain(levelId: string): number {
45|    return ambienceGain(this.volume, this.muted, levelById(this.ambience, levelId)?.gainDb ?? 0);
46|  }
47|
48|  private play(levelId: string): void {
49|    const level = levelById(this.ambience, levelId);
50|    if (!level || !this.unlocked) return;
51|    const at = ++this.seq;
52|    this.pendingId = levelId;
53|    const sources = level.sources;
54|    void this.engine.load(sources).then((handle) => {
55|      if (at !== this.seq) return;
56|      this.pendingId = null;
57|      const prev = this.voice;
58|      this.voice = null;
59|      // From off there is nothing to crossfade, so fade in instead.
60|      if (prev) prev.stop(CROSSFADE_SEC);
61|      this.voice = this.engine.start(handle, this.targetGain(levelId), prev ? CROSSFADE_SEC : FADE_IN_SEC);
62|    });
63|  }
64|
65|  setLevel(levelId: string): void {
66|    const next = levelById(this.ambience, levelId) ? levelId : "off";
67|    if (next === this.levelId) return;
68|    this.levelId = next;
69|    if (next === "off") {
70|      this.seq += 1;
71|      this.pendingId = null;
72|      const prev = this.voice;
73|      this.voice = null;
74|      prev?.stop(FADE_OUT_SEC);
75|      return;
76|    }
77|    this.play(next);
78|  }
79|
80|  setVolume(volume: number): void {
81|    this.volume = Number.isFinite(volume) ? Math.min(1, Math.max(0, volume)) : 0;
82|    this.voice?.ramp(this.targetGain(this.levelId), VOLUME_RAMP_SEC);
83|  }
84|
85|  setMuted(muted: boolean): void {
86|    this.muted = muted;
87|    this.voice?.ramp(this.targetGain(this.levelId), MUTE_FADE_SEC);
88|  }
89|
90|  async unlock(): Promise<void> {
91|    this.unlocked = true;
92|    await this.engine.unlock();
93|    if (this.levelId !== "off" && !this.voice && !this.pendingId) this.play(this.levelId);
94|  }
95|
96|  dispose(): void {
97|    this.seq += 1;
98|    this.pendingId = null;
99|    const prev = this.voice;
100|    this.voice = null;
101|    prev?.stop(0);
102|  }
103|}

